  "checks": [
    {
      "id": "REQ-TESTABILITY",
      "result": "PASS",
      "severity": "Critical",
      "finding": "REQ-001–012 specify observable routing, authorization, ownership, concurrency, verification and evidence outcomes. TEST-001–012 provide concrete positive and denial scenarios, including provider-specific substitution and preview-change tests."
    },
    {
      "id": "GOAL-AC-TRACE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Every stated goal REQ-001–012 maps explicitly to its corresponding AC-001–012 and TEST-001–012 in acceptance-tests.md."
    },
    {
      "id": "AC-OBSERVABLE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Acceptance criteria identify inspectable results: blocked writes, selected executors, unchanged historical bytes, retained legacy checks, original operation reconciliation, denied evidence completion and actual deployed-resource observations."
    },
    {
      "id": "SCOPE-BOUNDARY",
      "result": "PASS",
      "severity": "Major",
      "finding": "Non-goals explicitly exclude production provisioning, import, destructive rollback, generic deployment engines and Terraform/SAM/azd execution. Initial execution paths are Bicep and CDK; raw CloudFormation execution is explicitly blocked by AC-002."
    },
    {
      "id": "CONSTRAINTS-EXPLICIT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Roles, Security Boundaries and Assumptions define protected GitHub Actions authorization, separate prepare/apply permissions, scoped OIDC, immutable inputs, secret-free evidence and required deployment inputs. Historical #423 evidence is clearly distinguished from implementation of this new feature; its citations do not establish premature execution of cloud-orchestration."
    },
    {
      "id": "RISK-VALIDATION-SURFACE",
      "result": "PASS",
      "severity": "Major",
      "finding": "AC-004–010 cover authorization substitution, dependency drift, concurrency, replay, uncertain operations, brownfield mutation, unhealthy deployments and evidence attacks. Provider-specific observations and Evidence Rules distinguish live validation from fixtures and require separately authorized cleanup."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Major",
      "finding": "The host explicitly reports no domain/ directory; investigation.md independently records domain-sync skipped for that reason. The applicability condition is absent."
    }
  ]
